function solve({config,state,event}){
  let s=state||{mounted:true,query:'',current:null,loading:false,result:null,error:null};
  let e=event||{}, f=[];
  const reset=()=>({mounted:true,query:'',current:null,loading:false,result:null,error:null});
  if(!s.mounted){
    if(e.type==='mount')s=reset();
    return {state:s,output:{mounted:s.mounted,query:s.query,current:s.current,loading:s.loading,result:s.result,error:s.error,effects:f}};
  }
  if(e.type==='search'){
    if(s.loading)f.push({type:'cancel',id:s.current});
    s={mounted:true,query:e.query,current:e.id,loading:true,result:s.result,error:null};
    f.push({type:'request',id:e.id,query:e.query});
  }else if(e.type==='success'){
    if(s.loading&&s.current===e.id)s={mounted:true,query:s.query,current:s.current,loading:false,result:e.result,error:null};
  }else if(e.type==='failure'){
    if(s.loading&&s.current===e.id)s={mounted:true,query:s.query,current:s.current,loading:false,result:s.result,error:e.error};
  }else if(e.type==='cancel'){
    if(s.loading)f.push({type:'cancel',id:s.current});
    s={mounted:true,query:s.query,current:null,loading:false,result:s.result,error:null};
  }else if(e.type==='dispose'){
    if(s.loading)f.push({type:'cancel',id:s.current});
    s={mounted:false,query:'',current:null,loading:false,result:null,error:null};
  }
  return {state:s,output:{mounted:s.mounted,query:s.query,current:s.current,loading:s.loading,result:s.result,error:s.error,effects:f}};
}
